44	// printSessionCommand writes a single session resume command line to w.
45	// It appends a "(most recent)" label to the last entry in a multi-session list,
46	// and a "# prompt" comment when a prompt is available.
47	func printSessionCommand(w io.Writer, resumeCmd, prompt string, isMulti, isLast bool) {
48		comment := ""
49		if isMulti && isLast {
50			if prompt != "" {
51				comment = fmt.Sprintf("  # %s (most recent)", prompt)
52			} else {
53				comment = "  # (most recent)"
54			}
55		} else if prompt != "" {
56			comment = "  # " + prompt
57		}
58		fmt.Fprintf(w, "  %s%s\n", resumeCmd, comment)
59	}
